import yaml

def generate_deployment(name: str, image: str, replicas: int = 2) -> str:
    manifest = {
        'apiVersion': 'apps/v1',
        'kind': 'Deployment',
        'metadata': {'name': name, 'labels': {'app': name}},
        'spec': {
            'replicas': replicas,
            'selector': {'matchLabels': {'app': name}},
            'template': {
                'metadata': {'labels': {'app': name}},
                'spec': {
                    'containers': [{
                        'name': name,
                        'image': image,
                        'ports': [{'containerPort': 8080}]
                    }]
                }
            }
        }
    }
    return yaml.dump(manifest, default_flow_style=False)

print(generate_deployment('api-service', 'myrepo/api:v1.2', replicas=3))

