import click

@click.group()
def cli():
    """DevOps Automation CLI"""
    pass

@cli.command()
@click.option('--env', '-e', required=True,
              envvar='DEPLOY_ENV',
              help='Ambiente de deploy (production/staging)')
@click.option('--image', '-i', required=True,
              help='Imagem Docker com tag')
@click.option('--dry-run', is_flag=True, default=False,
              help='Simular sem executar')
def deploy(env: str, image: str, dry_run: bool):
    """Realiza deploy de uma imagem para o ambiente especificado"""
    click.echo(f'🚀 Deploy: {image} → {env}')
    if dry_run:
        click.secho('[DRY RUN] Nenhuma alteração aplicada', fg='yellow')

if __name__ == '__main__':
    cli()

